//! Env-file templates: `KEY=literal` lines are copied as written, and
//! `KEY=<store>://<path>` lines are replaced with the fetched secret.

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use anyhow::{bail, Context, Result};
use zeroize::Zeroizing;

use crate::store::{is_scheme_name, Reference, Schemes};

/// How every generated file starts; marks it as safe to overwrite.
const HEADER_PREFIX: &str = "# Generated by secretmap";

/// One parsed template line.
enum Line {
    /// Blank lines and comments.
    Verbatim(String),
    /// `KEY=value` with no store reference, copied as written.
    Literal {
        key: String,
        /// The original line, unchanged.
        line: String,
        /// The `scheme` of a `scheme://...` value.
        scheme: Option<String>,
    },
    /// `KEY=<store>://<path>`, replaced by the fetched, quoted value.
    Secret {
        key: String,
        /// Whether the line began with `export `.
        exported: bool,
        reference: Reference,
    },
}

/// A parsed env-file template.
pub struct Template {
    lines: Vec<Line>,
}

impl Template {
    /// Parse `text`. A value naming a declared store becomes a secret; one
    /// naming an undeclared store, or a quoted reference, is an error. Keys
    /// must be valid shell names and appear once.
    pub fn parse(text: &str, schemes: &Schemes) -> Result<Template> {
        let mut lines = Vec::new();
        let mut keys = BTreeSet::new();
        for (index, line) in text.lines().enumerate() {
            let number = index + 1;
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                lines.push(Line::Verbatim(line.to_string()));
                continue;
            }
            let (raw_key, raw_value) = trimmed
                .split_once('=')
                .with_context(|| format!("line {number}: expected KEY=value"))?;
            let key = raw_key.trim();
            let exported = key.starts_with("export ");
            let key = key.strip_prefix("export ").map_or(key, str::trim);
            if !valid_key(key) {
                bail!("line {number}: {key:?} isn't a valid key");
            }
            if !keys.insert(key.to_string()) {
                bail!("line {number}: {key} appears twice");
            }
            let value = raw_value.trim();
            let unquoted = value.trim_start_matches(['"', '\'']);
            let scheme = unquoted
                .split_once("://")
                .map(|(scheme, _)| scheme)
                .filter(|scheme| is_scheme_name(scheme));
            if let Some(scheme) = scheme {
                if schemes.undeclared.contains(scheme) {
                    bail!(
                        "line {number}: {key} uses store {scheme}, which the map doesn't \
                         declare: add it to the map's stores"
                    );
                }
                if unquoted != value && schemes.declared.contains(scheme) {
                    bail!(
                        "line {number}: {key}: remove the quotes around the {scheme}:// reference"
                    );
                }
            }
            match Reference::parse(value, &schemes.declared)
                .with_context(|| format!("line {number}"))?
            {
                Some(reference) => lines.push(Line::Secret {
                    key: key.to_string(),
                    exported,
                    reference,
                }),
                None => lines.push(Line::Literal {
                    key: key.to_string(),
                    line: line.to_string(),
                    scheme: scheme.map(str::to_string),
                }),
            }
        }
        Ok(Template { lines })
    }

    /// The references to fetch, in template order.
    pub fn references(&self) -> Vec<Reference> {
        self.lines
            .iter()
            .filter_map(|line| match line {
                Line::Secret { reference, .. } => Some(reference.clone()),
                _ => None,
            })
            .collect()
    }

    /// Every key, literal or secret, in template order.
    pub fn keys(&self) -> Vec<&str> {
        self.lines
            .iter()
            .filter_map(|line| match line {
                Line::Literal { key, .. } | Line::Secret { key, .. } => Some(key.as_str()),
                Line::Verbatim(_) => None,
            })
            .collect()
    }

    /// `(key, scheme)` of each literal whose value looks like `scheme://...`.
    pub fn literal_schemes(&self) -> Vec<(&str, &str)> {
        self.lines
            .iter()
            .filter_map(|line| match line {
                Line::Literal {
                    key,
                    scheme: Some(scheme),
                    ..
                } => Some((key.as_str(), scheme.as_str())),
                _ => None,
            })
            .collect()
    }

    /// The template with each secret replaced by its value from `secrets`,
    /// quoted for dotenv. Fails if a value is missing or can't be quoted.
    pub fn render(
        &self,
        secrets: &BTreeMap<Reference, Zeroizing<String>>,
    ) -> Result<Zeroizing<String>> {
        let mut out = Zeroizing::new(String::new());
        for line in &self.lines {
            match line {
                Line::Verbatim(text) | Line::Literal { line: text, .. } => out.push_str(text),
                Line::Secret {
                    key,
                    exported,
                    reference,
                } => {
                    let value = secrets
                        .get(reference)
                        .with_context(|| format!("no value fetched for {reference}"))?;
                    let quoted = quote(value).with_context(|| format!("{key} ({reference})"))?;
                    if *exported {
                        out.push_str("export ");
                    }
                    out.push_str(key);
                    out.push('=');
                    out.push_str(&quoted);
                }
            }
            out.push('\n');
        }
        Ok(out)
    }
}

/// The first lines of every generated file; `has_header` recognises them.
pub fn header(template: &Path, target: &str) -> String {
    format!(
        "{HEADER_PREFIX} from {}. Edit the template, not this file.\n\
         # Regenerate: secretmap pull --target {target}\n",
        template.display()
    )
}

/// Whether `text` starts with secretmap's generated-file header.
pub fn has_header(text: &str) -> bool {
    text.starts_with(HEADER_PREFIX)
}

/// `KEY -> raw value` for an env file, for comparing by key name.
///
/// Keys from a file secretmap didn't render are unvalidated text that may hold
/// secret material, so they must never be printed.
pub fn env_entries(text: &str) -> BTreeMap<String, Zeroizing<String>> {
    let mut entries = BTreeMap::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if let Some((key, value)) = trimmed.split_once('=') {
            let key = key.trim();
            let key = key.strip_prefix("export ").map_or(key, str::trim);
            entries.insert(key.to_string(), Zeroizing::new(value.trim().to_string()));
        }
    }
    entries
}

/// A shell variable name: a letter or `_`, then letters, digits or `_`.
fn valid_key(key: &str) -> bool {
    let mut chars = key.chars();
    chars
        .next()
        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

/// Quote a value so dotenv parsers and docker compose read it back unchanged.
fn quote(value: &str) -> Result<Zeroizing<String>> {
    // No `~`: a shell sourcing the file would expand it to a home directory.
    const PLAIN: &str = "-_./:@+=,%^";
    if value.contains(['\n', '\r']) {
        bail!("multi-line values aren't supported");
    }
    if !value.is_empty()
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || PLAIN.contains(c))
    {
        return Ok(Zeroizing::new(value.to_string()));
    }
    // Inside single quotes a shell keeps these as written, but dotenv parsers
    // read `\\` as one backslash and `\'` as a quote that doesn't close.
    if value.ends_with('\\') || value.contains("\\\\") {
        bail!("the value ends in \\ or contains \\\\, which dotenv parsers would misread");
    }
    if !value.contains('\'') {
        return Ok(Zeroizing::new(format!("'{value}'")));
    }
    if !value.contains(['"', '\\', '$', '`']) {
        return Ok(Zeroizing::new(format!("\"{value}\"")));
    }
    bail!("the value contains ' as well as one of \" \\ $ `, so it can't be quoted safely")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn schemes() -> Schemes {
        Schemes {
            declared: ["pass".to_string()].into(),
            undeclared: ["lp".to_string()].into(),
        }
    }

    fn reference(path: &str) -> Reference {
        Reference {
            store: "pass".into(),
            path: path.into(),
        }
    }

    #[test]
    fn parses_literals_secrets_and_comments() {
        let t = Template::parse(
            "# comment\n\nAPP_ENV=prod\nURL=https://api.example.com:8443\nexport SECRET=pass://Vault/item/field\n",
            &schemes(),
        )
        .unwrap();
        assert_eq!(t.keys(), vec!["APP_ENV", "URL", "SECRET"]);
        assert_eq!(t.references(), vec![reference("Vault/item/field")]);
    }

    #[test]
    fn unknown_scheme_is_a_literal() {
        let t = Template::parse("X=other://a/b\nY=plain\n", &schemes()).unwrap();
        assert!(t.references().is_empty());
        assert_eq!(t.literal_schemes(), vec![("X", "other")]);
    }

    #[test]
    fn quoted_references_are_refused() {
        for line in [
            "A=\"pass://V/i/f\"\n",
            "A='pass://V/i/f'\n",
            "A=\"pass://V/i/f\n",
        ] {
            let err = Template::parse(line, &schemes()).err().unwrap();
            assert!(
                err.to_string().contains("remove the quotes"),
                "{line}: {err}"
            );
        }
    }

    #[test]
    fn undeclared_stores_are_refused() {
        for line in ["A=lp://github/password\n", "A=\"lp://github/password\"\n"] {
            let err = Template::parse(line, &schemes()).err().unwrap();
            assert!(err.to_string().contains("doesn't declare"), "{line}: {err}");
        }
    }

    #[test]
    fn exported_secrets_stay_exported() {
        let t = Template::parse("export A=pass://V/i/f\nB=pass://V/i/f\n", &schemes()).unwrap();
        let mut secrets = BTreeMap::new();
        secrets.insert(reference("V/i/f"), Zeroizing::new("x".to_string()));
        assert_eq!(t.render(&secrets).unwrap().as_str(), "export A=x\nB=x\n");
    }

    #[test]
    fn rejects_duplicates_and_bad_lines() {
        assert!(Template::parse("A=1\nA=2\n", &schemes()).is_err());
        assert!(Template::parse("just text\n", &schemes()).is_err());
        assert!(Template::parse("1A=x\n", &schemes()).is_err());
        assert!(Template::parse("A=pass://\n", &schemes()).is_err());
    }

    #[test]
    fn renders_and_quotes() {
        let t = Template::parse("# c\nA=1\nB=pass://V/i/f\nC=pass://V/i/g\n", &schemes()).unwrap();
        let mut secrets = BTreeMap::new();
        secrets.insert(reference("V/i/f"), Zeroizing::new("abc-123".to_string()));
        secrets.insert(
            reference("V/i/g"),
            Zeroizing::new("has space #x".to_string()),
        );
        let out = t.render(&secrets).unwrap();
        assert_eq!(out.as_str(), "# c\nA=1\nB=abc-123\nC='has space #x'\n");
    }

    #[test]
    fn missing_secret_is_an_error() {
        let t = Template::parse("B=pass://V/i/f\n", &schemes()).unwrap();
        assert!(t.render(&BTreeMap::new()).is_err());
    }

    #[test]
    fn quoting() {
        assert_eq!(quote("a'b").unwrap().as_str(), "\"a'b\"");
        assert!(quote("a'b$c").is_err());
        assert!(quote("a\nb").is_err());
        assert_eq!(quote("").unwrap().as_str(), "''");
    }

    #[test]
    fn backslashes_are_kept_only_where_every_parser_agrees() {
        assert_eq!(quote("a\\b").unwrap().as_str(), "'a\\b'");
        assert_eq!(quote("C:\\dir\\new").unwrap().as_str(), "'C:\\dir\\new'");
        for value in ["ends\\", "a\\\\b", "a\\\\\\b"] {
            let err = quote(value).unwrap_err().to_string();
            assert!(err.contains("misread"), "{value}: {err}");
            assert!(!err.contains(value), "{err}");
        }
    }

    #[test]
    fn header_round_trip() {
        let h = header(Path::new("config/x.env.tpl"), "local");
        assert!(has_header(&h));
        assert!(!has_header("A=1\n"));
        assert!(env_entries(&h).is_empty());
    }
}
